selector_to_html = {"a[href=\"ImpingingDiagnostics.html#pyskyfire.injector.impinging.ImpingingDiagnostics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingDiagnostics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpingingDiagnostics</span></span></dt><dd><p>Mixing quantities of one impinging element.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">momentum</span></code> is the magnitude of the summed jet momentum [N] and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">resultant_angle</span></code> its angle from the chamber axis [rad].\n<code class=\"docutils literal notranslate\"><span class=\"pre\">mixture_ratio</span></code> is the element\u2019s oxidizer over fuel mass flow, NaN\nwithout fuel or without any oxidizer feed named. <code class=\"docutils literal notranslate\"><span class=\"pre\">rupe</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">momentum_flux_ratio</span></code> are oxidizer over fuel, and NaN unless the element\nhas exactly one fuel and one oxidizer jet.</p></dd>", "a[href=\"Jet.html#pyskyfire.injector.impinging.Jet\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.Jet\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Jet</span></span></dt><dd><p>One jet of an impinging element.</p></dd>", "a[href=\"ImpingingElement.html#pyskyfire.injector.impinging.ImpingingElement\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpingingElement</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">jets</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impingement_height</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../element/Element.html#pyskyfire.injector.element.Element\" title=\"pyskyfire.injector.element.Element\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.injector.element.Element</span></code></a></p><p>Jets drilled to meet at a point <code class=\"docutils literal notranslate\"><span class=\"pre\">impingement_height</span></code> above the face.</p></dd>", "a[href=\"#module-pyskyfire.injector.impinging\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.injector.impinging<a class=\"headerlink\" href=\"#module-pyskyfire.injector.impinging\" title=\"Link to this heading\">\u00b6</a></h1><p>Impinging elements: jets drilled so that they meet at one point.</p><p>An impinging element is a set of jets aimed at a common impingement point a\nheight above the face. Like and unlike doublets, triplets and pentads are the\nsame class with different jets: a like doublet has two jets on one feed, an\nunlike doublet one on each, an O-F-O triplet a fuel jet on the axis between two\noxidizer jets. Each jet\u2019s inclination is its own, so an unlike doublet can\nlean its jets unequally to point the resultant momentum down the axis.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
